window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b6d1b40752f1baf"]={"versions": [{"id": "FIG-8b6d1b40752f1baf", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Werkzeug-Interoperabilitätsdiagramm der AUTOSAR-Methodik. Das Diagramm visualisiert den dateibasierten Modellaustausch zwischen zwei Autorenwerkzeugen (<code>Authoring Tool 1</code> und <code>Authoring Tool 2</code>) über das standardisierte AUTOSAR-XML-Format (ARXML).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Authoring Tool 1 / Tool1</strong>: Quellwerkzeug, umfasst die Verarbeitungsschritte <code>edit description</code> und <code>create XML description</code> sowie den internen Zustand <code>changed internal representation</code>.\n</li><li><strong>Authoring Tool 2 / Tool2</strong>: Zielwerkzeug, umfasst die Verarbeitungsschritte <code>interpret XML description</code> und <code>edit description</code> sowie den internen Zustand <code>internal representation</code>.\n</li><li><strong>System Description (<code>.XML</code> / <code>:System</code>)</strong>: Standardisiertes AUTOSAR-XML-Artefakt als Austauschmedium.\n</li><li><strong>Schnittstellen / Relationen</strong>: Gerichtete Datenflusskanten (schwarze Pfeile) für interne Repräsentationsübergänge und Datei-Export/-Import; gestrichelte Zuordnungslinien von den Werkzeug-Icons (<code>Authoring Tool 1</code>, <code>Authoring Tool 2</code>) zu den jeweiligen Verarbeitungsschritten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Benutzer editiert im Quellwerkzeug (<code>Tool1</code>) das Modell über die Aktivität <code>edit description</code>.\n</li><li>Dies modifiziert die werkzeugeigene Datenstruktur (<code>changed internal representation</code>).\n</li><li>Die Aktivität <code>create XML description</code> serialisiert die interne Repräsentation und exportiert das Systemmodell in die Datei <code>system description</code> (<code>:System</code>, <code>.XML</code>).\n</li><li>Das Zielwerkzeug (<code>Tool2</code>) liest die Datei über <code>interpret XML description</code> ein und transformiert sie in die eigene <code>internal representation</code>.\n</li><li>Auf Basis der importierten Repräsentation erfolgt in <code>Tool2</code> die weitere Modellbearbeitung über <code>edit description</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das fundamentale Interoperabilitätsprinzip von AUTOSAR-Autorenwerkzeugen: Werkzeuge tauschen Modelle nicht über proprietäre Formate oder Direktkopplung aus, sondern ausschließlich über die verlustfreie Serialisierung und Deserialisierung standardisierter AUTOSAR-XML-Dateien gemäß AUTOSAR-Metamodell (<code>:System</code>). Werkzeughersteller müssen Importer und Exporter bereitstellen, die das AUTOSAR-XML-Schema syntaktisch und semantisch konform auf ihre internen Datenstrukturen abbilden.</p>"}, {"id": "FIG-5978515f2a2f71b8", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Werkzeug-Interoperabilitätsdiagramm der AUTOSAR-Methodik. Das Diagramm visualisiert den dateibasierten Modellaustausch zwischen zwei Autorenwerkzeugen (<code>Authoring Tool 1</code> und <code>Authoring Tool 2</code>) über das standardisierte AUTOSAR-XML-Format (ARXML).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Authoring Tool 1 / Tool1</strong>: Quellwerkzeug, umfasst die Verarbeitungsschritte <code>edit description</code> und <code>create XML description</code> sowie den internen Zustand <code>changed internal representation</code>.\n</li><li><strong>Authoring Tool 2 / Tool2</strong>: Zielwerkzeug, umfasst die Verarbeitungsschritte <code>interpret XML description</code> und <code>edit description</code> sowie den internen Zustand <code>internal representation</code>.\n</li><li><strong>System Description (<code>.XML</code> / <code>:System</code>)</strong>: Standardisiertes AUTOSAR-XML-Artefakt als Austauschmedium.\n</li><li><strong>Schnittstellen / Relationen</strong>: Gerichtete Datenflusskanten (schwarze Pfeile) für interne Repräsentationsübergänge und Datei-Export/-Import; gestrichelte Zuordnungslinien von den Werkzeug-Icons (<code>Authoring Tool 1</code>, <code>Authoring Tool 2</code>) zu den jeweiligen Verarbeitungsschritten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Benutzer editiert im Quellwerkzeug (<code>Tool1</code>) das Modell über die Aktivität <code>edit description</code>.\n</li><li>Dies modifiziert die werkzeugeigene Datenstruktur (<code>changed internal representation</code>).\n</li><li>Die Aktivität <code>create XML description</code> serialisiert die interne Repräsentation und exportiert das Systemmodell in die Datei <code>system description</code> (<code>:System</code>, <code>.XML</code>).\n</li><li>Das Zielwerkzeug (<code>Tool2</code>) liest die Datei über <code>interpret XML description</code> ein und transformiert sie in die eigene <code>internal representation</code>.\n</li><li>Auf Basis der importierten Repräsentation erfolgt in <code>Tool2</code> die weitere Modellbearbeitung über <code>edit description</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das fundamentale Interoperabilitätsprinzip von AUTOSAR-Autorenwerkzeugen: Werkzeuge tauschen Modelle nicht über proprietäre Formate oder Direktkopplung aus, sondern ausschließlich über die verlustfreie Serialisierung und Deserialisierung standardisierter AUTOSAR-XML-Dateien gemäß AUTOSAR-Metamodell (<code>:System</code>). Werkzeughersteller müssen Importer und Exporter bereitstellen, die das AUTOSAR-XML-Schema syntaktisch und semantisch konform auf ihre internen Datenstrukturen abbilden.</p>"}, {"id": "FIG-283bc9eaaee02fe9", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Werkzeug-Interoperabilitätsdiagramm der AUTOSAR-Methodik. Das Diagramm visualisiert den dateibasierten Modellaustausch zwischen zwei Autorenwerkzeugen (<code>Authoring Tool 1</code> und <code>Authoring Tool 2</code>) über das standardisierte AUTOSAR-XML-Format (ARXML).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Authoring Tool 1 / Tool1</strong>: Quellwerkzeug, umfasst die als Prozesspfeile dargestellten Schritte <code>edit description</code> und <code>create XML description</code> sowie den internen Zustand <code>changed internal representation</code>.\n</li><li><strong>Authoring Tool 2 / Tool2</strong>: Zielwerkzeug, umfasst den Verarbeitungsschritt <code>interpret XML description</code>, den internen Zustand <code>internal representation</code> und den als Prozesspfeil dargestellten Schritt <code>edit description</code>.\n</li><li><strong>System Description (<code>.XML</code> / <code>system description: System</code>)</strong>: Standardisiertes AUTOSAR-XML-Artefakt als Austauschmedium.\n</li><li><strong>Schnittstellen / Relationen</strong>: Gerichtete Datenflusskanten (schwarze Pfeile) für interne Repräsentationsübergänge und Datei-Export/-Import; gestrichelte Zuordnungslinien von den Werkzeug-Icons (<code>Authoring Tool 1</code>, <code>Authoring Tool 2</code>) zu den jeweiligen Verarbeitungsschritten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Benutzer editiert im Quellwerkzeug (<code>Tool1</code>) das Modell über die Aktivität <code>edit description</code>.\n</li><li>Dies modifiziert die werkzeugeigene Datenstruktur (<code>changed internal representation</code>).\n</li><li>Die Aktivität <code>create XML description</code> serialisiert die interne Repräsentation und exportiert das Systemmodell in die Datei <code>system description: System</code> (<code>.XML</code>).\n</li><li>Das Zielwerkzeug (<code>Tool2</code>) liest die Datei über <code>interpret XML description</code> ein und transformiert sie in die eigene <code>internal representation</code>.\n</li><li>Auf Basis der importierten Repräsentation erfolgt in <code>Tool2</code> die weitere Modellbearbeitung über <code>edit description</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das fundamentale Interoperabilitätsprinzip von AUTOSAR-Autorenwerkzeugen: Werkzeuge tauschen Modelle nicht über proprietäre Formate oder Direktkopplung aus, sondern ausschließlich über die verlustfreie Serialisierung und Deserialisierung standardisierter AUTOSAR-XML-Dateien gemäß AUTOSAR-Metamodell (<code>:System</code>). Werkzeughersteller müssen Importer und Exporter bereitstellen, die das AUTOSAR-XML-Schema syntaktisch und semantisch konform auf ihre internen Datenstrukturen abbilden.</p>"}], "trans": [{"from": "FIG-8b6d1b40752f1baf", "to": "FIG-5978515f2a2f71b8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5978515f2a2f71b8", "to": "FIG-283bc9eaaee02fe9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Prozessschritte <code>edit description</code> (in Tool1 und Tool2) sowie <code>create XML description</code> (in Tool1) werden von abgerundeten Rechtecken in chevronförmige Prozess-Pfeilsymbole (Blockpfeile nach rechts) geändert; die Beschriftung steht nun unterhalb der Formen statt innerhalb.\n</li><li>Die Beschriftung des XML-Artefakts wird von <code>system description</code> / <code>:System</code> auf <code>system description:</code> / <code>System</code> angepasst (Doppelpunkt hinter <code>description</code> statt vor <code>System</code>).\n</li></ul>"}]};
